"""Evaluate research requests against supplied evidence and policy."""

import copy
import json


def _result(status, value, sources, unknowns):
    """Build an output containing exactly the schema fields."""
    return {
        "status": status,
        "value": value,
        "sources": sources,
        "unknowns": unknowns,
    }


def _canonical_json(value):
    """Return a stable representation that preserves JSON value types."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def _superseded_ids(record):
    """Normalize the optional supersedes field to a sequence of source IDs."""
    supersedes = record.get("supersedes", [])
    if isinstance(supersedes, str):
        return [supersedes]
    if isinstance(supersedes, (list, tuple, set)):
        return supersedes
    return []


def evaluate(request, evidence, policy):
    """Evaluate one request using only the caller-supplied records and policy."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions")
    if not isinstance(request_conditions, dict):
        request_conditions = {}

    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return _result("unknown", None, [], missing)

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue

        record_conditions = record.get("conditions")
        if not isinstance(record_conditions, dict):
            continue
        if any(
            name not in record_conditions
            or _canonical_json(record_conditions[name])
            != _canonical_json(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = {
        source_id
        for record in eligible
        for source_id in _superseded_ids(record)
    }
    eligible = [
        record for record in eligible if record.get("source") not in superseded
    ]

    if not eligible:
        return _result("unknown", None, [], ["no matching evidence"])

    sources = sorted({record["source"] for record in eligible})
    values = {}
    for record in eligible:
        value = record.get("value")
        values.setdefault(_canonical_json(value), value)

    if len(values) != 1:
        return _result("conflict", None, sources, ["source disagreement"])

    value = copy.deepcopy(next(iter(values.values())))
    status = "unsupported" if value is False else "supported"
    return _result(status, value, sources, [])

